import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { COLORS, FONTS, STYLE, ENGRAVE_SHADOW } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const toList = (v: unknown): string[] => {
  if (Array.isArray(v)) return v.map((x) => String(x ?? "").trim()).filter(Boolean);
  if (typeof v === "string") return v.split(/\n|\|/).map((s) => s.trim()).filter(Boolean);
  return [];
};

const CartaoConsultorDestaque: React.FC<PrimitiveProps> = ({ anim, fps, format, frame }) => {
  const f = useCurrentFrame();
  const len = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const p = anim.params ?? {};
  const src = String(p.src ?? "").trim();
  const logo = String(p.logo ?? "").trim();
  const name = String(p.name ?? anim.text ?? "").trim();
  const role = String(p.role ?? "").trim();
  let buttons = toList(p.buttons);
  if (!buttons.length && p.phone) buttons = [String(p.phone).trim()];

  const W = frame.width;
  const H = frame.height;
  const portrait = format === "portrait";
  const landscape = format === "landscape";
  const u = Math.min(W, H) / 1080;
  const m = 56 * u;
  const pad = (portrait ? 40 : 32) * u;
  const r = (px: number) => (STYLE.sharp ? 0 : px * u);

  const nameBase = (portrait ? 96 : landscape ? 84 : 64) * u;
  const nameSize = nameBase * Math.min(1, Math.max(0.5, Math.sqrt(16 / Math.max(1, name.length))));
  const roleSize = (portrait ? 34 : 30) * u;
  const btnSize = (portrait ? 34 : 30) * u;

  // Timing: everything settles by ~55% of the layer; fades out in the last 0.4s.
  const at = (q: number) => Math.round(q * len);
  const sp = (q: number, damping = 200) =>
    spring({ frame: f - at(q), fps, config: { damping }, durationInFrames: Math.max(6, at(0.18)) });
  const exit = interpolate(f, [len - Math.round(0.4 * fps), len], [1, 0], clamp);
  const cardIn = sp(0);
  const photoIn = sp(0.06);
  const nameIn = sp(0.2);
  const roleIn = sp(0.26);
  const logoIn = sp(0.4 + buttons.length * 0.05);

  // Photo sits flush against the card edge (no border, outline or inset frame); the card clips its corners.
  const photo = (
    <div
      style={{
        position: "relative",
        overflow: "hidden",
        background: src ? undefined : "rgba(255,255,255,.06)",
        flex: portrait ? "0 0 auto" : "0 0 64%",
        width: portrait ? "100%" : undefined,
        height: portrait ? H * 0.6 : "100%",
        opacity: photoIn,
      }}
    >
      {src ? (
        <Img
          src={src}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
            scale: String(interpolate(f, [0, at(0.4)], [1.14, 1], { ...clamp, easing: Easing.out(Easing.cubic) })),
          }}
        />
      ) : (
        <AbsoluteFill style={{ justifyContent: "center", alignItems: "center" }}>
          <span style={{ color: COLORS.mutedOnDark, fontSize: roleSize }}>Fotografia</span>
        </AbsoluteFill>
      )}
    </div>
  );

  const info = (
    <div
      style={{
        flex: 1,
        minWidth: 0,
        padding: pad,
        boxSizing: "border-box",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: portrait ? "center" : "flex-start",
        textAlign: portrait ? "center" : "left",
        gap: (portrait ? 22 : 18) * u,
      }}
    >
      {name ? (
        <div
          style={{
            fontFamily: FONTS.display,
            fontWeight: FONTS.displayWeight,
            fontSize: nameSize,
            lineHeight: 1.04,
            letterSpacing: "-0.01em",
            color: "rgba(255,255,255,1)",
            textShadow: `0 0 ${28 * u}px rgba(255,255,255,.55), 0 0 ${8 * u}px rgba(255,255,255,.35), ${ENGRAVE_SHADOW}`,
            overflowWrap: "break-word",
            maxWidth: "100%",
            opacity: nameIn,
            translate: `0px ${(1 - nameIn) * 30 * u}px`,
          }}
        >
          {name}
        </div>
      ) : null}
      {role ? (
        <div
          style={{
            fontWeight: FONTS.bodyWeight,
            fontSize: roleSize,
            lineHeight: 1.3,
            color: COLORS.mutedOnDark,
            overflowWrap: "break-word",
            maxWidth: "100%",
            opacity: roleIn,
            translate: `0px ${(1 - roleIn) * 20 * u}px`,
          }}
        >
          {role}
        </div>
      ) : null}
      {buttons.length ? (
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            justifyContent: portrait ? "center" : "flex-start",
            gap: 16 * u,
            marginTop: 8 * u,
          }}
        >
          {buttons.map((b, i) => {
            const t = sp(0.32 + i * 0.05, 14);
            return (
              <div
                key={i}
                style={{
                  background: COLORS.leather,
                  color: "rgba(255,255,255,1)",
                  borderRadius: r(12),
                  padding: `${20 * u}px ${32 * u}px`,
                  fontWeight: 700,
                  fontSize: btnSize,
                  lineHeight: 1.1,
                  overflowWrap: "break-word",
                  maxWidth: "100%",
                  opacity: Math.min(1, t * 1.5),
                  scale: String(0.7 + 0.3 * t),
                }}
              >
                {b}
              </div>
            );
          })}
        </div>
      ) : null}
      <div
        style={{
          marginTop: 10 * u,
          height: 136 * u,
          maxWidth: 580 * u,
          padding: `${12 * u}px ${20 * u}px`,
          boxSizing: "border-box",
          borderRadius: r(12),
          background: logo ? "rgba(255,255,255,1)" : "rgba(255,255,255,.06)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          opacity: logoIn,
          translate: `0px ${(1 - logoIn) * 20 * u}px`,
        }}
      >
        {logo ? (
          <Img src={logo} style={{ height: "100%", width: "auto", maxWidth: "100%", objectFit: "contain" }} />
        ) : (
          <span style={{ color: COLORS.mutedOnDark, fontSize: roleSize * 0.8 }}>Logótipo</span>
        )}
      </div>
    </div>
  );

  return (
    <AbsoluteFill
      style={{
        fontFamily: FONTS.body,
        justifyContent: "center",
        alignItems: "center",
        padding: m,
        boxSizing: "border-box",
        opacity: exit,
      }}
    >
      <div
        style={{
          width: "100%",
          height: portrait ? undefined : "100%",
          boxSizing: "border-box",
          overflow: "hidden",
          borderRadius: r(24),
          background: COLORS.ink,
          display: "flex",
          flexDirection: portrait ? "column" : "row",
          alignItems: "stretch",
          opacity: cardIn,
          translate: `0px ${(1 - cardIn) * 60 * u}px`,
        }}
      >
        {photo}
        {info}
      </div>
    </AbsoluteFill>
  );
};

export default CartaoConsultorDestaque;

